// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Leaves".

Yet another attempt at painting in a shader. This time with a
subtle animation, as if a gentle breeze were blowing across the lake.

Interaction:
- Space Bar: Pause/Play
- Mouse Wheel: Zoom
- Mouse Move: Pan
*/

const scale = Math.max(1, devicePixelRatio)
let theShader, moves=[0,0], wheelDelta = 0, wheelOffset = 0, pause = false, paused = 0, time = 0;

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/3017691/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function mouseMove() {
	if (!((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) return
	moves[0] += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) * scale
	moves[1] += ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) * scale
}

function mouseWheel(e) {
	if (wheelDelta * e.deltaY < 0) {
		wheelDelta = e.deltaY
	} else {
		wheelDelta = lerp(wheelDelta, e.deltaY, 0.05)
	}
	wheelOffset += wheelDelta
}

function keyPressed(e) {
	if (e.key === " ") {
		if (!pause) {
			pause = true
		} else {
			pause = false
			paused = millis() - time
		}
	}
}

function draw() {
  mouseMove()
  shader(theShader)
  if (!pause) time = millis() - paused
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("move", moves)
  theShader.setUniform("wheel", [wheelDelta, wheelOffset])
  theShader.setUniform("time", time / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 move;
uniform vec2 wheel;
#define FC gl_FragCoord.xy
#define R resolution
#define T time
#define S smoothstep
#define SE(v,a) S(a+1./MN,a-1./MN,v)
#define MN min(R.x,R.y)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
#define hue(a) (.5+.5*sin(3.14*(a)+vec3(0,1,2)))
float rnd(vec2 a) {
	vec3 p=fract(a.xyx*.1031);
	p+=dot(p,p.yzx+33.33);
	return fract((p.x+p.y)*p.z);
}
float noise(vec2 p) {
	vec2 i=floor(p), u=S(i,i+1.,p), k=vec2(1,0);
	float
	a=rnd(i),
	b=rnd(i+k),
	c=rnd(i+k.yx),
	d=rnd(i+k.xx);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
float fbm(vec2 p) {
	float t=.0, a=1.; mat2 m=mat2(1.2,-.8,1,1.2);
	for (int i=0; i<5; i++) {
		t+=a*noise(p);
		p*=m*2.;
		a/=2.;
	}
	return t;
}
vec3 background(vec2 uv, float k, out float d) {
	vec3 col=vec3(1);
	vec2 t=vec2(sin(T),cos(T));
	float e=max(abs(uv.x)+.05,abs(uv.y-.05)-.0125*fbm(uv.xx*33.));
	d=SE(e,.3-.005*fbm(uv.yx*120.));
	vec3 sea=hue(fbm(uv-.02*t-vec2(fbm(uv.yx*vec2(8,1)),2))-fbm(uv.xx*5.-.1)*.25+fbm(uv*12.-.125*k)*.125+.58);
	col=mix(col,mix(sea,pow(sea,vec3(1.15)),k),d);
	col=mix(col,vec3(dot(col,vec3(.21,.71,.07))),d*(1.-mix(.3,.5,fbm(uv.yy*4.+.5))));
	col=mix(col,vec3(dot(col,vec3(.21,.71,.07))),sqrt(tanh(e*e)));
	return col;
}
vec3 tree(vec2 uv, float k, out float d) {
	vec3 col=vec3(1);
	vec2 p=uv+vec2(0,.25), q=p+vec2(-.02,.07), t=vec2(sin(T),cos(T));
	q*=vec2(.5,2.);
	float f=length(q);
	f=SE(f,.01+.01*fbm(q.yx*33.33+1.2-.06*t)+mix(.0,.005,fbm(q*333.)));
	col=mix(col,vec3(.2)-.02*k,f);
	p.x-=.008*sin(62.*p.y+2.2);
	p.y-=clamp(p.y,-.07,.05);
	float e=length(p);
	e=SE(e,.01-.005*fbm(uv*33.33+8.));
	col=mix(col,vec3(.1)-.05*k,e);
	d=length(uv+vec2(0,.2));
	float bloom=mix(.9,.005,noise(uv*323.+1.-.4*t));
	uv.y+=.05;
	d=SE(d,.05-.01*sin(12.*fbm(uv.yx*12.))+bloom*.05);
	vec3 leaves=mix(.8,1.1,bloom)*hue(1.8*fbm(uv-vec2(fbm(uv*3.),3))-fbm(uv*40.-.1*t)*.25+fbm(uv*12.-.02*t+.5*k)*.125+.5);
	col=mix(col,mix(sqrt(tanh(leaves*leaves))*1.2,leaves,k),d);
	d=max(max(d,e),f);
	return col;
}
vec3 paper(vec2 uv, float k, out float d) {
	vec3 col=vec3(1);
	uv=vec2(abs(uv.x)-.3-.0025*fbm(uv.yy*2.-22.*fbm(uv.yx*13.37-.42)),abs(uv.y)-.4-.0025*fbm(uv.xx-2.*fbm(uv.yx*22.22)));
	d=max(uv.x,uv.y);
	d=SE(d,.07-.01*fbm(uv));
	col=mix(col,mix(vec3(.98,.94,.9),vec3(.95,.92,.9),k),d);
	return col;
}
vec3 signature(vec2 uv, float k, out float d) {
	vec3 col=vec3(0);
	vec2 t=vec2(sin(T),cos(T)), p=uv*13.+vec2(-2.5,2.6)-.01*t;
	p.y+=.2*sin(p.x*33.-12.3*p.y-1.2*sin(p.x*10.-2.)-cos(p.x*10.+1.));
	p.y+=.2*(sin(p.y)-sin(p.x*2.));
	p.x-=clamp(p.x,-.2,.2);
	d=length(p-.03*t);
	d=SE(d,.15);
	col+=mix(col,mix(vec3(.98,.94,.9),vec3(.97,.92,.9),k),d);
	return col;
}
vec3 render(vec2 uv) {
	vec3 col=vec3(0);
	float zoom=.5*sin(wheel.y/1e3);
	uv.y-=move.y/MN;
	uv.x-=move.x/MN;
	uv*=1.+zoom;
	float c,d,e,f,h=200.+fbm(uv.yx*22.),
	k=sin(uv.x*h+uv.y*h*2.)-sin(uv.x*h-uv.y*h*2.);
	col=mix(col,paper(uv,k,c),c);
	col=mix(col,background(uv,k,d),d);
	col=mix(col,tree(uv,k,e),e);
	col=mix(col,signature(uv,k,f),f);
	col=mix(mix(vec3(.95,.92,.9)*.1,vec3(.9,.87,.85)*.1,k),col,max(c,max(d,max(e,f))));
	return col;
}
void main() {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=render(uv*(R.y>R.x?.95:1.));
	vec2 c=FC/R;
	c*=1.-c.yx;
	float v=c.x*c.y*25.;
	col=mix(tanh(col*col*col)*.2,col,clamp(pow(v,.125),.0,1.));
	O=vec4(col,1);
}

